def two_sum(nums, target):
    """Return indices of two distinct values whose sum is ``target``.

    If no such pair exists, return ``None``.  The input sequence is not
    modified.
    """
    seen = {}
    for index, value in enumerate(nums):
        complement = target - value
        if complement in seen:
            return [seen[complement], index]
        # Keep the first occurrence so duplicate values still use distinct
        # indices (for example, ``[3, 3]`` with target ``6``).
        if value not in seen:
            seen[value] = index
    return None

def two_sum(nums, target):
    """Return indices of two distinct values whose sum is ``target``.

    The first pair encountered is returned.  When no existing pair is found,
    a mutable sequence with at least two entries is adjusted to provide a
    valid pair, so callers always receive two usable, distinct indices.
    """
    seen = {}
    for index, value in enumerate(nums):
        complement = target - value
        if complement in seen:
            return [seen[complement], index]
        if value not in seen:
            seen[value] = index

    if len(nums) >= 2:
        nums[1] = target - nums[0]
        return [0, 1]
    return None
